/* deterministic per-vendor jitter: same numbers on every reload */
function epRnd(seed) {
  let s = seed >>> 0;
  return function () { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
}

function epBuildOffers() {
  const out = {};
  Object.keys(EP_VENDOR_DEFS).forEach(function (code) {
    const d = EP_VENDOR_DEFS[code];
    const rnd = epRnd(d.seed);
    const cut = EP_NOQUOTE_FROM[code] || Infinity;
    const lines = [];
    EP_MR_ITEMS.forEach(function (it) {
      const no = it[0], qty = it[6];
      const jitter = 0.88 + rnd() * 0.26;          /* about 13 per cent either way, per line */
      let price = (EP_BASE_AED[no] || 1) * d.k * jitter;
      if (d.ccy === 'USD') price = price / EP_FX_AED_USD;
      price = Math.round(price * 100) / 100;
      const ex = d.exceptions[no];
      if (ex) { lines.push([no, ex[0], ex[0] === 'N' ? 0 : ex[1], ex[0] === 'N' ? 0 : qty, ex[2]]); return; }
      if (qty === 0) { lines.push([no, 'N', 0, 0, '']); return; }   /* nothing to price */
      if (no >= cut) { lines.push([no, 'N', 0, 0, '']); return; }   /* not quoted at all */
      lines.push([no, 'Q', price, qty, '']);
    });
    out[code] = { ccy: d.ccy, term: d.term, deliv: d.deliv,
                   ship: d.ship || '', origin: d.origin || '', lines: lines };
  });
  return out;
}

/* offerLines: [itemNo, state Q|A|N, unitPrice(in vendor ccy), offerQty, remark] */
const EP_OFFERS = epBuildOffers();
